package com.vandorlabs.neoforge.copifier;
import com.google.gson.*;
import com.vandorlabs.neoforge.propulsion.*;
import java.nio.file.*;
import java.io.*;
import java.util.zip.GZIPInputStream;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.level.block.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
/** Canonical placed engines/hover callbacks, opaque ownership, independent saved restart; no Vehicle. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeCopifierPropulsionWorldChecks {
 private static final BlockPos POS=new BlockPos(20600,82,20600);private static int checks;
 private static void need(boolean value,String text){checks++;if(!value)throw new AssertionError("Copied placed propulsion: "+text);}
 private static NativePropulsionEntity at(ServerLevel world,BlockPos pos){return (NativePropulsionEntity)world.getBlockEntity(pos);}
 private static NativePropulsionEntity put(ServerLevel world,BlockPos pos,String id,int meta,CompoundTag data){world.getChunkAt(pos);world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);var block=NativePropulsionRegistrations.BLOCKS.get(id).get();world.setBlock(pos,block.defaultBlockState().setValue(NativePropulsionBlock.FACING,Direction.from3DDataValue((meta&7)%6)).setValue(NativePropulsionBlock.POWERED,(meta&8)!=0),18);var owner=at(world,pos);var input=data.copy();input.putString("CopiedEngineMarker","retained");input.putByteArray("CopiedEnginePayload",new byte[65536]);var cap=new CompoundTag();cap.putString("Owner","opaque:engine");input.put("ForgeCaps",cap);owner.loadWithComponents(input,world.registryAccess());owner.onLoad();need(owner.available(),"installed available owner");return owner;}
 private static net.neoforged.neoforge.common.util.FakePlayer actor(ServerLevel world){var player=new net.neoforged.neoforge.common.util.FakePlayer(world,new com.mojang.authlib.GameProfile(java.util.UUID.fromString("13802c63-120b-435b-9894-0a0651c7906d"),"CopiedEngine"));player.setPos(POS.getX()+.5,POS.getY(),POS.getZ()+2);player.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);return player;}
 private static void write(ServerLevel world)throws Exception{var player=actor(world);int count=0;try(var lines=new BufferedReader(new InputStreamReader(new GZIPInputStream(Files.newInputStream(Path.of(System.getProperty("vandorlabs.copifierPropulsionReference")))),java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=lines.readLine())!=null){var row=JsonParser.parseString(line).getAsJsonObject();var owner=put(world,POS,row.get("block").getAsString(),row.get("meta").getAsInt(),TagParser.parseTag(row.get("target").getAsString()));var facing=owner.getBlockState().getValue(NativePropulsionBlock.FACING);var values=TagParser.parseTag(row.get("values").getAsString());var original=values.copy();need(NativeCopifierPropulsionEdit.capture(owner).equals(TagParser.parseTag(row.get("before").getAsString())),"Source initial case="+count);boolean result=owner.configureCopied(values,player);need(result==row.get("applied").getAsBoolean(),"Source result case="+count);var expected=TagParser.parseTag(row.get("after").getAsString());var actual=NativeCopifierPropulsionEdit.capture(owner);need(expected.equals(actual),"Source final case="+count+" values="+values+" expected="+expected+" actual="+actual);need(world.getBlockEntity(POS)==owner&&owner.getBlockState().getValue(NativePropulsionBlock.FACING)==facing&&values.equals(original),"physical owner/facing/clipboard case="+count);need(((NativePropulsionBlock)owner.getBlockState().getBlock()).definition().id.equals(row.get("afterBlock").getAsString()),"resulting Source shape case="+count);var saved=owner.saveWithoutMetadata(world.registryAccess());need(saved.getString("CopiedEngineMarker").equals("retained")&&saved.getByteArray("CopiedEnginePayload").length==65536&&saved.getCompound("ForgeCaps").getString("Owner").equals("opaque:engine"),"opaque owner fields case="+count);count++;}}need(count==8694,"whole Source corpus");
 groups(world,player);
 var groupData=new CompoundTag();groupData.putBoolean("ManualOn",true);groupData.putBoolean("LightInitialized",true);groupData.putInt("ParticleLevel",1);groupData.putInt("PropulsionSideTexture",64);var peers=new NativePropulsionEntity[4];for(int i=0;i<4;i++)peers[i]=put(world,POS.offset(i%2,i/2,0),"rocket_thruster",10,groupData);NativePropulsionService.refresh(peers[0]);need(peers[0].visual().part().size()==2,"actual 2x2 Source assembly before copy");var groupEdit=new CompoundTag();groupEdit.putInt("propulsion_shape",1);groupEdit.putInt("wall_texture",7);groupEdit.putInt("particles",3);need(peers[0].configureCopied(groupEdit,player),"assembly shape then leaf settings");for(int i=0;i<4;i++){need(world.getBlockEntity(peers[i].getBlockPos())==peers[i]&&((NativePropulsionBlock)peers[i].getBlockState().getBlock()).definition().shape==1,"all four physical owners convert geometry");need(peers[i].settings().data().sideTexture==(i==0?7:64)&&peers[i].settings().data().particleLevel==(i==0?3:1),"copied scalar settings affect only selected leaf");}for(int i=0;i<4;i++)world.setBlock(peers[i].getBlockPos(),Blocks.AIR.defaultBlockState(),18);
 var bare=put(world,POS,"rocket_thruster",2,new CompoundTag());var shapeOnly=new CompoundTag();shapeOnly.putInt("propulsion_shape",1);need(bare.configureCopied(shapeOnly,player)&&bare.visual().definition().shape==1,"shape-only copy publishes resulting immutable body immediately");world.setBlock(POS,Blocks.AIR.defaultBlockState(),18);
 var owner=put(world,POS,"rocket_thruster",2,new CompoundTag());var mixed=new CompoundTag();mixed.putInt("propulsion_shape",1);mixed.putInt("wall_texture",7);mixed.putBoolean("active",true);mixed.putInt("particles",3);need(owner.configureCopied(mixed,player)&&((NativePropulsionBlock)owner.getBlockState().getBlock()).definition().shape==1&&owner.settings().data().sideTexture==7&&owner.settings().data().manualOn&&owner.settings().data().particleLevel==3,"shape then all copied settings on same selected physical owner");var before=owner.saveWithoutMetadata(world.registryAccess());var worker=owner;need(!java.util.concurrent.CompletableFuture.supplyAsync(()->worker.configureCopied(mixed,player)).join()&&worker.saveWithoutMetadata(world.registryAccess()).equals(before),"worker refuses before world/ownership reads");var invalid=new CompoundTag();invalid.putInt("propulsion_shape",99);invalid.putInt("wall_texture",17);need(!owner.configureCopied(invalid,player)&&owner.saveWithoutMetadata(world.registryAccess()).equals(before),"invalid shape refuses before settings mutation");
 var badPos=POS.east(3);var bad=put(world,badPos,"rocket_thruster",2,new CompoundTag());var future=bad.saveWithoutMetadata(world.registryAccess());future.putInt("NativePropulsionSchema",99);bad.loadWithComponents(future,world.registryAccess());need(bad.inert()&&!bad.configureCopied(mixed,player)&&bad.saveWithoutMetadata(world.registryAccess()).equals(future),"inert original retained exactly");var retired=owner;world.setBlock(POS,Blocks.AIR.defaultBlockState(),18);need(!retired.configureCopied(mixed,player),"stale identity refuses");owner=put(world,POS,"rocket_thruster",2,new CompoundTag());need(owner.configureCopied(mixed,player),"saved copied shape");world.setChunkForced(POS.getX()>>4,POS.getZ()>>4,true);
 }
 private static void groups(ServerLevel world,ServerPlayer player)throws Exception{
  var previous=new java.util.ArrayList<BlockPos>();int count=0;try(var lines=new BufferedReader(new InputStreamReader(new GZIPInputStream(Files.newInputStream(Path.of(System.getProperty("vandorlabs.copifierPropulsionGroupReference")))),java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=lines.readLine())!=null){for(var pos:previous)world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);previous.clear();var row=JsonParser.parseString(line).getAsJsonObject();var input=TagParser.parseTag(row.get("input").getAsString());var owners=new java.util.ArrayList<NativePropulsionEntity>();for(var element:row.getAsJsonArray("before")){var cell=element.getAsJsonObject();var pos=POS.offset(cell.get("dx").getAsInt(),cell.get("dy").getAsInt(),cell.get("dz").getAsInt());previous.add(pos);var owner=put(world,pos,cell.get("block").getAsString(),row.get("face").getAsInt()|8,input);owners.add(owner);need(NativeCopifierPropulsionEdit.capture(owner).equals(TagParser.parseTag(cell.get("capture").getAsString())),"Source group initial case="+count);}NativePropulsionService.refresh(owners.getFirst());need(owners.getFirst().visual().part().size()==2,"real joined group case="+count);var values=TagParser.parseTag(row.get("values").getAsString());need(owners.getFirst().configureCopied(values,player)==row.get("applied").getAsBoolean(),"Source group result case="+count);var expected=row.getAsJsonArray("after");for(int i=0;i<4;i++){var owner=owners.get(i);var cell=expected.get(i).getAsJsonObject();need(world.getBlockEntity(owner.getBlockPos())==owner,"Source physical group owner="+count+":"+i);need(((NativePropulsionBlock)owner.getBlockState().getBlock()).definition().id.equals(cell.get("block").getAsString())&&NativeCopifierPropulsionEdit.capture(owner).equals(TagParser.parseTag(cell.get("capture").getAsString())),"Source geometry/selected scalar group case="+count+":"+i);}count++;}}for(var pos:previous)world.setBlock(pos,Blocks.AIR.defaultBlockState(),18);need(count==72,"full Source group callback coverage");
 }
 private static void read(ServerLevel world){world.getChunkAt(POS);var owner=at(world,POS);need(owner!=null&&((NativePropulsionBlock)owner.getBlockState().getBlock()).definition().shape==1&&owner.settings().data().sideTexture==7&&owner.settings().data().manualOn&&owner.settings().data().particleLevel==3,"copied shape and settings restart");var saved=owner.saveWithoutMetadata(world.registryAccess());need(saved.getString("CopiedEngineMarker").equals("retained")&&saved.getByteArray("CopiedEnginePayload").length==65536&&saved.getCompound("ForgeCaps").getString("Owner").equals("opaque:engine"),"opaque owner restart");var failed=at(world,POS.east(3));need(failed.inert()&&failed.saveWithoutMetadata(world.registryAccess()).getInt("NativePropulsionSchema")==99,"inert retained restart");}
 @SubscribeEvent public static void started(ServerStartedEvent event)throws Exception{var phase=System.getProperty("vandorlabs.transmitterPhase","");if(!phase.startsWith("copifier-propulsion-"))return;var world=event.getServer().overworld();if(phase.endsWith("write"))write(world);else read(world);event.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][copifier-propulsion] "+(phase.endsWith("write")?"write":"read")+" PASS checks="+checks);event.getServer().halt(false);}
}
